$nodeScript = @'
const fs = require('fs')
const { PNG } = require('pngjs')
const pixelmatch = require('pixelmatch')
const actual = PNG.sync.read(fs.readFileSync('D:/repository/苏住房G/worktrees/task2468-navbar-visual/e2e/artifacts/task2468-navbar-visual/navbar-visual-1920.png'))
const reference = PNG.sync.read(fs.readFileSync('D:/repository/苏住房G/worktrees/task2468-navbar-visual/e2e/home-v2/fixtures/navbar-reference.png'))
function crop(img, x, y, width, height) {
  const data = Buffer.alloc(width * height * 4)
  for (let row = 0; row < height; row++) img.data.copy(data, row * width * 4, ((y + row) * img.width + x) * 4, ((y + row) * img.width + x + width) * 4)
  return data
}
const bands = [['top', 0, 20], ['content', 20, 92], ['bottom', 92, 18]]
const regions = [['brand', 0, 400], ['active', 400, 200], ['nav-a', 600, 400], ['nav-b', 1000, 400], ['nav-c', 1400, 280], ['arrow', 1680, 42], ['gap', 1722, 112], ['user', 1834, 86]]
for (const [region, x, width] of regions) {
  const rows = []
  for (const [band, y, height] of bands) {
    const mismatched = pixelmatch(crop(actual, x, y, width, height), crop(reference, x, y, width, height), null, width, height, { threshold: 0.1, includeAA: false })
    rows.push(`${band}=${(100 * (1 - mismatched / (width * height))).toFixed(1)}%`)
  }
  console.log(`${region}: ${rows.join(' ')}`)
}
'@
node -e $nodeScript
